<template>
    <div>
        <Head title="Icons" />

        <Card title="Icon Catalog">
            <div class="row align-items-end gy-3 mb-4">
                <div class="md:col-5">
                    <label for="icon-search">Search icon names</label>
                    <input id="icon-search" v-model="query" type="search" class="form-control" placeholder="Search by name" />
                </div>
                <div class="md:col-4">
                    <span id="icon-set-label" class="d-block">Icon set</span>
                    <Select42
                        v-model="iconSet"
                        class="w-100"
                        aria-labelledby="icon-set-label"
                        :options="iconSetOptions"
                        :show-search="false"
                        :allow-clear="false"
                    />
                </div>
                <div class="md:col-3">
                    <a v-if="activeCatalog.googleSet" :href="googleFontsUrl" target="_blank" rel="noopener noreferrer">Open in Google Fonts</a>
                    <a v-else href="https://fontawesome.com/v4/icons/" target="_blank" rel="noopener noreferrer">Open Font Awesome</a>
                </div>
            </div>

            <p role="status">
                {{ matchingIcons.length.toLocaleString('en') }} matching {{ matchingIcons.length === 1 ? 'icon' : 'icons' }}
            </p>
            <p v-if="!matchingIcons.length">Try another name or switch icon sets.</p>

            <div v-if="selectedMarkup" class="mb-4">
                <label for="icon-markup">Vue markup</label>
                <input
                    id="icon-markup"
                    ref="markup"
                    type="text"
                    class="form-control"
                    :value="selectedMarkup"
                    readonly
                    @focus="$event.target.select()"
                />
                <small role="status">{{ copyMessage }}</small>
            </div>

            <div v-if="matchingIcons.length" class="icon-results">
                <button
                    v-for="name in matchingIcons.slice(0, visibleCount)"
                    :key="name"
                    type="button"
                    class="btn btn-outline icon-result"
                    :aria-label="`Copy markup for ${name}`"
                    @click="copyIcon(name)"
                >
                    <i :class="iconClass(name)" class="icon-preview" aria-hidden="true">{{ activeCatalog.googleSet ? name : '' }}</i>
                    <span>{{ name }}</span>
                </button>
            </div>

            <button
                v-if="visibleCount < matchingIcons.length"
                type="button"
                class="btn btn-outline mt-3"
                @click="visibleCount += pageSize"
            >
                Show more
            </button>
        </Card>
    </div>
</template>

<script>
import { Head } from '@inertiajs/vue3';
import Card from '@scaffold/components/Card.vue';
import materialIcons from '../../../../fonts/material-catalogs/MaterialIcons-Regular.codepoints?raw';
import materialSymbols from '../../../../fonts/material-catalogs/MaterialSymbolsOutlined.codepoints?raw';
import fontAwesomeStyles from '../../../../fonts/fontawesome-4.7.0.css?raw';
import Select42 from '@sulzanoks/select42';

const pageSize = 72;

function iconNames(codepoints) {
    const names = codepoints.trim().split(/\r?\n/)
        .map((line) => line.split(/\s+/)[0])
        .filter((name) => /^[a-z0-9_]+$/.test(name));

    return [...new Set(names)];
}

export default {
    name: 'IconsDemo',
    components: { Card, Head, Select42 },
    layout: { pageTitle: 'Icons' },
    data() {
        return {
            query: '',
            iconSet: 'icons',
            pageSize,
            visibleCount: pageSize,
            selectedMarkup: '',
            copyMessage: '',
            catalogs: {
                icons: {
                    label: 'Material Icons',
                    googleSet: 'Material Icons',
                    iconClass: 'material-icons',
                    names: iconNames(materialIcons),
                },
                symbols: {
                    label: 'Material Symbols Outlined',
                    googleSet: 'Material Symbols',
                    iconClass: 'material-symbols-outlined',
                    names: iconNames(materialSymbols),
                },
                fontAwesome: {
                    label: 'Font Awesome 4.7',
                    iconClass: 'fa',
                    names: [...new Set([...fontAwesomeStyles.matchAll(/\.fa-([a-z0-9-]+):before\b/g)]
                        .map((match) => match[1]))].sort(),
                },
            },
        };
    },
    computed: {
        iconSetOptions() {
            return Object.entries(this.catalogs).map(([value, catalog]) => ({ value, text: catalog.label }));
        },
        activeCatalog() {
            return this.catalogs[this.iconSet];
        },
        matchingIcons() {
            const search = this.query.trim().toLowerCase();
            const query = this.activeCatalog.googleSet
                ? search.replace(/[\s-]+/g, '_')
                : search.replace(/[\s_]+/g, '-').replace(/^fa-/, '');
            return this.activeCatalog.names.filter((name) => name.includes(query));
        },
        googleFontsUrl() {
            const params = new URLSearchParams({ 'icon.set': this.activeCatalog.googleSet });
            if (this.query.trim()) {
                params.set('icon.query', this.query.trim());
            }
            return `https://fonts.google.com/icons?${params}`;
        },
    },
    watch: {
        query() {
            this.visibleCount = this.pageSize;
        },
        iconSet() {
            this.visibleCount = this.pageSize;
            this.selectedMarkup = '';
            this.copyMessage = '';
        },
    },
    methods: {
        iconClass(name) {
            const { googleSet, iconClass } = this.activeCatalog;
            return googleSet ? iconClass : `${iconClass} fa-${name}`;
        },
        async copyIcon(name) {
            const content = this.activeCatalog.googleSet ? name : '';
            const markup = `<i class="${this.iconClass(name)}" aria-hidden="true">${content}</i>`;
            this.selectedMarkup = markup;
            this.copyMessage = '';

            if (navigator.clipboard) {
                try {
                    await navigator.clipboard.writeText(markup);
                    if (this.selectedMarkup === markup) {
                        this.copyMessage = 'Copied to clipboard.';
                    }
                    return;
                } catch {
                    // Select the markup for manual copying when clipboard access is denied.
                }
            }

            if (this.selectedMarkup === markup) {
                this.copyMessage = 'Press Ctrl+C or Command+C to copy.';
                await this.$nextTick();
                this.$refs.markup?.focus();
            }
        },
    },
};
</script>

<style scoped>
.icon-results {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(8rem, 1fr));
    gap: .5rem;
}

.icon-result {
    display: grid;
    justify-items: center;
    align-content: center;
    gap: .5rem;
    min-block-size: 5.5rem;
    min-inline-size: 0;
    margin: 0;
    padding: .75rem .375rem;
    text-transform: none;
    overflow-wrap: anywhere;
}

.icon-result .icon-preview {
    position: static;
    margin: 0;
    font-size: 1.75rem;
    line-height: 1;
    white-space: nowrap;
}
</style>
